// True concurrent HTTP writers: exactly one acquisition and one revision advance.
function race($op,$requests){$multi=curl_multi_init();$handles=[];foreach($requests as [$p,$t]){$h=curl_init('http://127.0.0.1/index.php?controller=NativeApiController&action=handle&plugin=FamilyHub');curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$t],CURLOPT_POSTFIELDS=>json_encode(['v'=>1,'op'=>$op,'params'=>(object)$p],JSON_THROW_ON_ERROR)]);curl_multi_add_handle($multi,$h);$handles[]=$h;}do{curl_multi_exec($multi,$active);if($active){curl_multi_select($multi,1);}}while($active);$results=[];foreach($handles as $h){$results[]=json_decode(curl_multi_getcontent($h),true,32,JSON_THROW_ON_ERROR);curl_multi_remove_handle($multi,$h);curl_close($h);}curl_multi_close($multi);return$results;}
